import React from 'react';
import { useTheme } from '@hexa-ui/theme';
import { Container } from './IconButton.styles';
import { IconButtonTypes } from './IconButton.types';
import { getIconSize } from './utils/getIconSize';
import { LoadingDots } from '../spinner';

const IconButtonComponent = (
  {
    size = 'medium',
    loading = false,
    elevation = false,
    variant = 'primary',
    icon: Icon,
    onClick,
    ...props
  }: IconButtonTypes,
  forwardedRef: React.ForwardedRef<HTMLButtonElement>
): JSX.Element => {
  const theme = useTheme();

  if (size === 'tiny' && (variant === 'primary' || variant === 'secondary')) {
    return <></>;
  }

  return (
    <Container
      variant={variant}
      sizevariant={size}
      elevation={elevation}
      onClick={onClick}
      {...props}
      className={`${props.className ? props.className : ''} ${theme}`}
      ref={forwardedRef}
    >
      {loading ? (
        <LoadingDots
          size={size === 'large' ? 'large' : 'medium'}
          color={variant === 'primary' ? 'colorful' : 'mono'}
          dataTestId="LoadingDots"
        />
      ) : (
        <Icon size={getIconSize(size)} />
      )}
    </Container>
  );
};

export const IconButton = React.forwardRef(IconButtonComponent);
export default IconButton;
